import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { studentsAPI, facultyAPI, attendanceAPI, marksAPI, departmentsAPI, batchesAPI, subjectsAPI } from '../services/api';
import {
  Users,
  GraduationCap,
  BookOpen,
  Calendar,
  Award,
  Building,
  TrendingUp,
  Activity,
} from 'lucide-react';

const Dashboard = () => {
  const { user } = useAuth();
  const [stats, setStats] = useState({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDashboardStats();
  }, [user]);

  const fetchDashboardStats = async () => {
    try {
      setLoading(true);
      console.log('Fetching dashboard stats...');
      const responses = await Promise.all([
        studentsAPI.getAll(),
        facultyAPI.getAll(),
        departmentsAPI.getAll(),
        batchesAPI.getAll(),
        subjectsAPI.getAll(),
        attendanceAPI.getReport(),
        marksAPI.getReport(),
      ]);

      console.log('Dashboard API responses:', responses);

      const studentsData = responses[0].data || [];
      const facultyData = responses[1].data || [];
      const departmentsData = responses[2].data || [];
      const batchesData = responses[3].data || [];
      const subjectsData = responses[4].data || [];
      const attendanceData = responses[5].data || {};
      const marksData = responses[6].data || {};

      console.log('Dashboard processed data:', {
        studentsData,
        facultyData,
        departmentsData,
        batchesData,
        subjectsData,
        attendanceData,
        marksData
      });

      setStats({
        totalStudents: studentsData.length,
        totalFaculty: facultyData.length,
        totalDepartments: departmentsData.length,
        totalBatches: batchesData.length,
        totalSubjects: subjectsData.length,
        attendanceRate: attendanceData.attendance_percentage || 0,
        averageMarks: marksData.percentage || 0,
        activeStudents: studentsData.filter(s => s.status === 'active').length,
        totalAttendance: attendanceData.total_records || 0,
        totalMarks: marksData.total_records || 0,
      });
    } catch (error) {
      console.error('Error fetching dashboard stats:', error);
    } finally {
      setLoading(false);
    }
  };

  const getWelcomeMessage = () => {
    const hour = new Date().getHours();
    if (hour < 12) return 'Good Morning';
    if (hour < 17) return 'Good Afternoon';
    return 'Good Evening';
  };

  const getRoleSpecificStats = () => {
    switch (user?.role) {
      case 'admin':
        return [
          {
            title: 'Total Students',
            value: stats.totalStudents || 0,
            icon: Users,
            color: 'bg-blue-500',
            change: '+12%',
            changeType: 'increase',
          },
          {
            title: 'Total Faculty',
            value: stats.totalFaculty || 0,
            icon: GraduationCap,
            color: 'bg-green-500',
            change: '+5%',
            changeType: 'increase',
          },
          {
            title: 'Departments',
            value: stats.totalDepartments || 0,
            icon: Building,
            color: 'bg-purple-500',
            change: 'Active',
            changeType: 'neutral',
          },
          {
            title: 'Batches',
            value: stats.totalBatches || 0,
            icon: Calendar,
            color: 'bg-indigo-500',
            change: 'Total',
            changeType: 'neutral',
          },
          {
            title: 'Subjects',
            value: stats.totalSubjects || 0,
            icon: BookOpen,
            color: 'bg-pink-500',
            change: 'Available',
            changeType: 'neutral',
          },
          {
            title: 'Attendance Rate',
            value: `${stats.attendanceRate || 0}%`,
            icon: Activity,
            color: 'bg-orange-500',
            change: '+3%',
            changeType: 'increase',
          },
        ];

      case 'faculty':
        return [
          {
            title: 'My Subjects',
            value: '6',
            icon: BookOpen,
            color: 'bg-blue-500',
            change: '+2',
            changeType: 'increase',
          },
          {
            title: 'Classes Today',
            value: '4',
            icon: Calendar,
            color: 'bg-green-500',
            change: '0',
            changeType: 'neutral',
          },
          {
            title: 'Total Students',
            value: '120',
            icon: Users,
            color: 'bg-purple-500',
            change: '+15',
            changeType: 'increase',
          },
          {
            title: 'Avg Attendance',
            value: `${stats.attendanceRate || 0}%`,
            icon: TrendingUp,
            color: 'bg-orange-500',
            change: '+3%',
            changeType: 'increase',
          },
        ];

      case 'student':
        return [
          {
            title: 'My Attendance',
            value: `${stats.attendanceRate || 0}%`,
            icon: Calendar,
            color: 'bg-blue-500',
            change: '+2%',
            changeType: 'increase',
          },
          {
            title: 'Average Marks',
            value: `${stats.averageMarks || 0}%`,
            icon: Award,
            color: 'bg-green-500',
            change: '+5%',
            changeType: 'increase',
          },
          {
            title: 'Subjects',
            value: '8',
            icon: BookOpen,
            color: 'bg-purple-500',
            change: '0',
            changeType: 'neutral',
          },
          {
            title: 'Current Semester',
            value: user?.details?.semester || '3',
            icon: GraduationCap,
            color: 'bg-orange-500',
            change: 'Current',
            changeType: 'neutral',
          },
        ];

      default:
        return [];
    }
  };

  const StatCard = ({ title, value, icon: Icon, color, change, changeType }) => (
    <div className="bg-white rounded-xl shadow-lg hover:shadow-xl transition-shadow duration-300 p-6 border border-secondary-100">
      <div className="flex items-center justify-between mb-4">
        <div className={`${color} rounded-lg p-3 shadow-md`}>
          <Icon className="h-6 w-6 text-white" />
        </div>
        <div className="text-right">
          {changeType === 'increase' && (
            <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-green-100 text-green-800">
              <TrendingUp className="h-3 w-3 mr-1" />
              {change}
            </span>
          )}
          {changeType === 'decrease' && (
            <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-red-100 text-red-800">
              <TrendingUp className="h-3 w-3 mr-1 rotate-180" />
              {change}
            </span>
          )}
          {changeType === 'neutral' && (
            <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-gray-100 text-gray-600">
              {change}
            </span>
          )}
        </div>
      </div>
      <div>
        <p className="text-sm font-medium text-secondary-600 mb-1">{title}</p>
        <p className="text-3xl font-bold text-secondary-900">{value}</p>
      </div>
    </div>
  );

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-7xl mx-auto px-2 sm:px-4 lg:px-6 py-4">
        {/* Welcome Section */}
        <div className="bg-gradient-to-r from-primary-600 to-primary-800 rounded-2xl shadow-xl p-6 text-white mb-6">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between">
            <div>
              <h1 className="text-2xl sm:text-3xl font-bold mb-2">
                {getWelcomeMessage()}, {user?.details?.first_name || user?.username}!
              </h1>
              <p className="text-primary-100">
                Welcome back to the Medical College Management System
              </p>
            </div>
            <div className="mt-3 sm:mt-0">
              <div className="bg-white/20 backdrop-blur-sm rounded-lg px-3 py-2">
                <p className="text-xs font-medium">Role</p>
                <p className="text-base font-semibold capitalize">{user?.role}</p>
              </div>
            </div>
          </div>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4 mb-6">
          {getRoleSpecificStats().map((stat, index) => (
            <StatCard key={index} {...stat} />
          ))}
        </div>

        {/* Quick Actions */}
        <div className="bg-white rounded-xl shadow-lg p-4">
          <h2 className="text-lg font-bold text-secondary-900 mb-4">Quick Actions</h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3">
            {user?.role === 'admin' && (
              <>
                <button className="group p-4 border border-secondary-200 rounded-xl hover:bg-secondary-50 hover:border-primary-300 transition-all duration-200 text-left">
                  <div className="flex items-center mb-2">
                    <div className="bg-blue-100 group-hover:bg-blue-200 rounded-lg p-2 transition-colors">
                      <Users className="h-5 w-5 text-blue-600" />
                    </div>
                  </div>
                  <h3 className="font-semibold text-secondary-900 mb-1">Add Student</h3>
                  <p className="text-xs text-secondary-500">Register a new student</p>
                </button>
                <button className="group p-4 border border-secondary-200 rounded-xl hover:bg-secondary-50 hover:border-primary-300 transition-all duration-200 text-left">
                  <div className="flex items-center mb-2">
                    <div className="bg-green-100 group-hover:bg-green-200 rounded-lg p-2 transition-colors">
                      <GraduationCap className="h-5 w-5 text-green-600" />
                    </div>
                  </div>
                  <h3 className="font-semibold text-secondary-900 mb-1">Add Faculty</h3>
                  <p className="text-xs text-secondary-500">Hire new faculty member</p>
                </button>
                <button className="group p-4 border border-secondary-200 rounded-xl hover:bg-secondary-50 hover:border-primary-300 transition-all duration-200 text-left">
                  <div className="flex items-center mb-2">
                    <div className="bg-purple-100 group-hover:bg-purple-200 rounded-lg p-2 transition-colors">
                      <Building className="h-5 w-5 text-purple-600" />
                    </div>
                  </div>
                  <h3 className="font-semibold text-secondary-900 mb-1">Manage Departments</h3>
                  <p className="text-xs text-secondary-500">Organize departments</p>
                </button>
                <button className="group p-4 border border-secondary-200 rounded-xl hover:bg-secondary-50 hover:border-primary-300 transition-all duration-200 text-left">
                  <div className="flex items-center mb-2">
                    <div className="bg-indigo-100 group-hover:bg-indigo-200 rounded-lg p-2 transition-colors">
                      <Calendar className="h-5 w-5 text-indigo-600" />
                    </div>
                  </div>
                  <h3 className="font-semibold text-secondary-900 mb-1">View Reports</h3>
                  <p className="text-xs text-secondary-500">Analytics & insights</p>
                </button>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
